WITH kept_keys AS (SELECT country, city FROM customers EXCEPT SELECT country, city FROM customers WHERE country NOT IN ('US', 'TH')), kept_rows AS (SELECT s.* FROM customers s JOIN kept_keys k ON s.country = k.country AND s.city = k.city) SELECT DATE_TRUNC('QUARTER', signup_date) AS quarter_start, city, DATE_TRUNC('WEEK', signup_date) AS week_start, COUNT(*) AS cnt, PERCENTILE_APPROX(age, 0.95) AS age_p95, DENSE_RANK() OVER (PARTITION BY DATE_TRUNC('QUARTER', signup_date) ORDER BY PERCENTILE_APPROX(age, 0.95) DESC) AS age_p95_dense_rank FROM kept_rows GROUP BY 1, 2, 3 ORDER BY quarter_start DESC
